# Response-model defaults survive skip-default serialization

A route configured to skip response-model defaults still emits a field whose
value is the model default when the handler returns a model instance. Diagnose
where model semantics are lost and state the smallest correction and check.


VISIBLE ARTIFACT: buggy_impl.py (buggy_source)
"""Reduced reproduction of FastAPI bug 10 at b77a43bc."""


class ResponseModel:
    def __init__(self, name: str, note: str | None = None) -> None:
        self.name = name
        self.note = note

    def dict(self, *, skip_defaults: bool = False) -> dict[str, str | None]:
        result: dict[str, str | None] = {"name": self.name, "note": self.note}
        if skip_defaults and self.note is None:
            result.pop("note")
        return result


def serialize_response(response: ResponseModel, *, skip_defaults: bool) -> dict[str, str | None]:
    value = {"name": response.name, "note": response.note}
    return dict(value)


VISIBLE ARTIFACT: check.py (test)
from types import ModuleType


def verify(implementation: ModuleType) -> None:
    response = implementation.ResponseModel(name="Ada")
    assert implementation.serialize_response(response, skip_defaults=True) == {"name": "Ada"}
    assert implementation.serialize_response(response, skip_defaults=False) == {
        "name": "Ada",
        "note": None,
    }
